const Corte: React.FC<{t: number; antes: React.ReactNode; despues: React.ReactNode}> = ({t, antes, despues}) => {
  const {s} = useS();
  return <AbsoluteFill>{s < t ? antes : despues}</AbsoluteFill>;
};

// ---------- tiempos (todo atado a palabras del guion) ----------
const AVISO1 = en('aviso', 1), ULTIMA = en('ultima'), APURARTE = en('apurarte'), REINO1 = en('reino', 1), TUVIERON = en('tuvieron'), FRENARLO = en('frenarlo');
const BUSCAS = en('buscas'), HOTEL1 = en('hotel', 1), ARRIBA = en('arriba'), ROJO1 = en('rojo', 1), QUEDAN = en('quedan', 1), DOS1 = en('dos', 1), DIEZ = en('diez'), VIENDO = en('viendo'), ESTO = en('esto');
const TE1 = en('te', 1), APURAS = en('apuras'), PAGAS1 = en('pagas', 1), COMPARAR = en('comparar'), CIERTO = en('cierto');
const LA1 = en('la', 1), AUTORIDAD = en('autoridad'), REINO2 = en('reino', 2), INVESTIGO = en('investigo'), PAGINAS = en('paginas', 1), RESERVAS = en('reservas'), DIECINUEVE = en('diecinueve'), SEIS = en('seis'), COMPROM = en('comprometieron'), CAMBIAR = en('cambiar');
const QUE2 = en('que', 2), DABAN = en('daban'), TODO5 = en('todo'), AGOTABA = en('agotaba'), VECES = en('veces'), HABIT2 = en('habitaciones'), PAGINA1 = en('pagina', 1), HOTEL2 = en('hotel', 2);
const LA3 = en('la', 3), PRISA1 = en('prisa', 1), TRUCO = en('truco'), PRISA2 = en('prisa', 2), COMPARAS = en('comparas'), PAGAS2 = en('pagas', 2), PONGAN = en('pongan');
const CUANDO = en('cuando'), AVISO2 = en('aviso', 2), ROJO2 = en('rojo', 2), RESPIRA = en('respira'), BUSCA = en('busca'), HOTEL3 = en('hotel', 3), OTRA = en('otra'), PAGINA2 = en('pagina', 2), SUYA = en('suya'), PAGAR = en('pagar');
const DALE = en('dale'), LIKE = en('like'), COMENTA = en('comenta'), APURADO = en('apurado'), PAGASTE = en('pagaste'), PRISA3 = en('prisa', 3), ENVIASELO = en('enviaselo'), VIAJE = en('viaje');
const OFF = '#3a3f4a';

// ---------- el reloj de arena rojo: gira cada vez mas rapido y al final se detiene ----------
const VEL = (s: number) => interpolate(s, [0, DOS1, TE1, LA1, PRISA1, PRISA1 + 3, RESPIRA - 0.3, RESPIRA + 0.3], [40, 80, 160, 220, 420, 1000, 1000, 0], clamp);
const ANGT: number[] = (() => { const o = [0]; for (let i = 1; i <= Math.ceil(DUR * 30) + 90; i++) o.push(o[i - 1] + VEL(i / 30) / 30); return o; })();
const ANGEND = ANGT[Math.floor((RESPIRA + 0.3) * 30)];
const CORR = Math.round(ANGEND / 360) * 360 - ANGEND;
const giro = (s: number) => {
  const f = Math.max(0, s) * 30, i = Math.min(ANGT.length - 2, Math.floor(f));
  return ANGT[i] + (ANGT[i + 1] - ANGT[i]) * (f - i) + CORR * ro(s, RESPIRA - 1.5, RESPIRA + 0.3);
};
const arena = (a: number) => 0.5 + 0.5 * Math.cos((a * Math.PI) / 180);

const Reloj: React.FC<{x: number; y: number; k?: number; rot?: number; p?: number; col?: string}> = ({x, y, k = 1, rot = 0, p = 1, col = RED}) => {
  const vidrio = 'M -80 -140 Q -80 -40 -10 0 Q -80 40 -80 140 L 80 140 Q 80 40 10 0 Q 80 -40 80 -140 Z';
  const top = 140 * (1 - p), alto = 130 * (1 - p);
  return (
    <g transform={`translate(${x} ${y}) rotate(${rot}) scale(${k})`}>
      <defs><clipPath id="relojC"><path d={vidrio} /></clipPath></defs>
      <circle r={210} fill={col} opacity={0.12} />
      <path d={vidrio} fill="rgba(255,255,255,0.14)" />
      <g clipPath="url(#relojC)">
        <rect x={-90} y={-140 + top} width={180} height={140 - top} fill={col} />
        <rect x={-90} y={140 - alto} width={180} height={alto + 2} fill={col} />
        {p > 0.02 && p < 0.98 && <rect x={-3} y={0} width={6} height={140 - alto} fill={col} />}
        <path d="M -60 -120 Q -64 -60 -30 -20" stroke="rgba(255,255,255,0.55)" strokeWidth={9} fill="none" strokeLinecap="round" />
      </g>
      <path d={vidrio} fill="none" stroke="rgba(255,255,255,0.7)" strokeWidth={7} strokeLinejoin="round" />
      <rect x={-104} y={-166} width={208} height={30} rx={10} fill="#3b2412" stroke="#150c06" strokeWidth={4} />
      <rect x={-104} y={136} width={208} height={30} rx={10} fill="#3b2412" stroke="#150c06" strokeWidth={4} />
    </g>
  );
};

const Ojo: React.FC<{x: number; y: number; k?: number; mx: number; my: number}> = ({x, y, k = 1, mx, my}) => {
  const a = Math.atan2(my - y, mx - x);
  return (
    <g transform={`translate(${x} ${y}) scale(${k})`}>
      <ellipse rx={56} ry={34} fill="#fffdf6" stroke="#222" strokeWidth={5} />
      <circle cx={Math.cos(a) * 20} cy={Math.sin(a) * 12} r={18} fill="#3a2a1a" />
      <circle cx={Math.cos(a) * 20 - 5} cy={Math.sin(a) * 12 - 6} r={5} fill="#fff" />
    </g>
  );
};

