      <g transform={`translate(620 136) scale(${pu * ban}) translate(-620 -136)`} opacity={1 - apagado * 0.5}>
        <rect x={420} y={80} width={400} height={112} rx={16} fill={apagado > 0.5 ? '#8a6a6a' : RED} stroke="#8a1414" strokeWidth={5} />
        <text x={650} y={156} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={62} fill="#fff">SOLO 2</text>
        <Reloj x={472} y={136} k={0.26} rot={rot} p={p} col="#fff2f2" />
      </g>
      {viendo > 0.02 && (
        <g transform={`translate(620 236) scale(${viendo}) translate(-620 -236)`}>
          <rect x={420} y={210} width={400} height={54} rx={27} fill="#ff9b3d" stroke="#a85a10" strokeWidth={4} />
          <ellipse cx={460} cy={237} rx={22} ry={14} fill="#fff" /><circle cx={460} cy={237} r={8} fill="#3a2a1a" />
