// ================= SITIO A: el aviso rojo en macro (E1 y E8) =================
const PA = {x: 15, y: 640, k: 1.25};
const SA_CAM = [P(0, 760, 830, 1.65), P(ULTIMA, 700, 850, 1.45), P(APURARTE, 760, 840, 1.7), P(REINO1, 620, 900, 1.3), P(FRENARLO, 760, 830, 1.6), P(FRENARLO + 1.4, 650, 900, 1.25)];
const SH_CAM = [P(DALE - 0.2, 700, 860, 1.5), P(APURADO, 740, 840, 1.4), P(ENVIASELO, 650, 900, 1.25), P(DUR, 620, 930, 1.15)];
const SitioA: React.FC<{fin?: boolean}> = ({fin = false}) => {
  const {s} = useS();
  const barra = fin ? 0 : eo(ro(s, FRENARLO - 0.2, FRENARLO + 0.3));
  const reb = fin ? 0 : golpe(s, FRENARLO + 0.3, 28, 9) * 12;
  const ang = fin ? 0 : giro(s);
  return (
    <AbsoluteFill>
      <Camara paradas={fin ? SH_CAM : SA_CAM}>
        <Textura tipo="fibra" base="radial-gradient(circle at 50% 45%, #2b2f3c 0%, #14161e 70%, #07080c 100%)" linea="rgba(160,180,255,0.14)" luz="rgba(160,180,255,0.08)" semilla={181} />
        <svg width={1080} height={1920} style={{position: 'absolute', inset: 0}}>
          <rect x={PA.x - 28} y={PA.y - 28} width={840 * PA.k + 56} height={520 * PA.k + 56} rx={30} fill="#0e1016" stroke="#2c303c" strokeWidth={6} />
          <g transform={`translate(${PA.x} ${PA.y}) scale(${PA.k})`}><Pagina ban={1} pulso={fin ? 0 : barra > 0.5 ? 0 : 1} p={fin ? 1 : arena(ang)} rot={ang} apagado={barra} /></g>
          {!fin && barra > 0.01 && (
            <g transform={`translate(790 ${760 + (1 - barra) * -420 + reb})`}>
              <rect x={-310} y={-26} width={620} height={52} rx={12} fill="#fff" stroke="#222" strokeWidth={5} />
              {Array.from({length: 9}).map((_, i) => <polygon key={i} points={`${-300 + i * 70},-24 ${-260 + i * 70},-24 ${-290 + i * 70},24 ${-330 + i * 70},24`} fill={RED} />)}
              <Mano x={0} y={-150} r={180} k={0.8} dedo={false} piel={1} manga="#3c4660" largo={600} />
            </g>
          )}
        </svg>
        <Brillo x={790} y={830} r={fin ? 300 : 460} color={fin ? 'rgba(255,200,61,0.25)' : 'rgba(255,60,60,0.5)'} />
        {!fin && <Ondas x={790} y={830} t0={FRENARLO + 0.3} color={GOLD} radio={420} />}
        <Polvo n={14} color="rgba(190,200,255,0.4)" />
      </Camara>
    </AbsoluteFill>
  );
